    }
}

fun undoBookmarkRemoval() {
    viewModelScope.launch {
        lastRemovedBookmarkId?.let {
            userDataRepository.setNewsResourceBookmarked(it, true)
        }
    }
    clearUndoState()
}

fun clearUndoState() {
    shouldDisplayUndoBookmark = false
    lastRemovedBookmarkId = null
}

